var input = $input.first().json.data || $input.first().json;
var allowed = ['contract_ready','revised_offer','re_engagement'];
var decisionType = String(input.decisionType || '').toLowerCase();
var protectedMao = input.protectedMAO;
var offerAmount = Number(input.offerAmount);
var humanReview = input.humanReviewRequired === true || decisionType === 'human_review';
var suppressed = input.suppressed === true || input.dnc === true;
var validAmount = Number.isFinite(offerAmount) && offerAmount > 0;
var valid = allowed.indexOf(decisionType) !== -1 && validAmount && !humanReview && !suppressed && Number.isFinite(Number(protectedMao)) && offerAmount <= Number(protectedMao);
return [{ json: { ...input, decisionType: decisionType, offerAmount: offerAmount, valid: valid, blockedReason: humanReview ? 'human_review_required' : suppressed ? 'seller_suppressed_or_dnc' : !validAmount ? 'invalid_offer_amount' : allowed.indexOf(decisionType) === -1 ? 'unsupported_decision_type' : Number(offerAmount) > Number(protectedMao) ? 'offer_exceeds_protected_mao' : null } }];

var d = $input.first().json;
var decisionId = String(d.decisionId || '');
var dealId = String(d.dealId || '');
var sellerId = String(d.sellerId || '');
var idem = 'wf373:' + decisionId + ':' + dealId + ':' + String(d.offerAmount);
var packageBody = { decisionId: decisionId, dealId: dealId, sellerId: sellerId, decisionType: d.decisionType, offerAmount: Number(d.offerAmount), terms: d.approvedTerms || {}, sellerMessage: d.sellerMessage || null, responseWindow: d.responseWindow || null };
return [{ json: { ...d, idempotencyKey: idem, sellerOfferPackage: packageBody } }];
